var t=`0503-maftoul`;var n=`world-0503`;var o=`PS`;var a=`western-asia`;var r=4;var s=79;var l={en:`Maftoul`,ua:`Мафту́ль`};var d={en:`A traditional dish from Palestine, centered on yellow onion, chicken thigh, canned chickpeas, tomato. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Палестина. Основні складники: жовта цибуля, куряче стегно, консервований нут, помідор. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,200,`g`],[`extra-virgin-olive-oil`,55,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 40 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 40 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:40,i:[[`chicken-thigh`,600,`g`],[`canned-chickpeas`,350,`g`],[`tomato`,300,`g`],[`water`,700,`ml`],[`allspice-berries`,4,`g`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 22 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 22 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:22,i:[[`pearl-couscous`,330,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:8,i:[]}];var u={slug:t,id:n,country:`PS`,region:a,servings:4,minutes:79,title:l,text:d,steps:g};export{o as country,u as default,n as id,s as minutes,a as region,r as servings,t as slug,g as steps,d as text,l as title};